window.PM={meta:{titre:"Ma\xEEtrise des risques d'une fintech en phase de croissance",organisation:"PayMaroc (cas fictif)",sujet:"Sujet 04",groupe:"G5",filiere:"G\xE9nie Financier \u2013 5GF",ecole:"EMSI Tanger",annee:"2026\u20132027",professeur:"Prof. Zenab Elmenzhi",membres:["BENCHRIF Mohamed Youssef","ABERCHAN Youssef"],problematique:"Comment accompagner la croissance d'une fintech tout en structurant la responsabilit\xE9 des acteurs et la ma\xEEtrise des risques ?",regleCotation:"P \xD7 G est une r\xE8gle p\xE9dagogique de classement qualitatif. Ce n'est ni une probabilit\xE9 statistique, ni une perte attendue, ni une mesure financi\xE8re du risque.",bareme:"1\u20135 : faible \xB7 6\u201312 : mod\xE9r\xE9 \xB7 15\u201325 : \xE9lev\xE9",departage:"Classement : score P \xD7 G d\xE9croissant ; \xE0 \xE9galit\xE9, gravit\xE9 d\xE9croissante, puis probabilit\xE9 d\xE9croissante, puis identifiant.",horsPerimetre:"VaR, mod\xE8les PD/LGD, ALM, actuariat/solvabilit\xE9, d\xE9riv\xE9s de couverture, simulations avanc\xE9es, audit d\xE9taill\xE9 des cycles et r\xE9f\xE9rentiel AMMC (r\xE9serv\xE9 au sujet 02) ne sont pas utilis\xE9s dans ce travail.",references:["Committee of Sponsoring Organizations of the Treadway Commission. (2013). Internal control \u2013 Integrated framework. COSO.","EMSI Tanger. (s. d.). Livret de projet \u2013 Contr\xF4le continu int\xE9gr\xE9 5GF (Sujet 04 : PayMaroc). \xC9cole Marocaine des Sciences de l'Ing\xE9nieur.","EMSI Tanger. (s. d.). Supports de cours et TD de Contr\xF4le interne (s\xE9ances 1 \xE0 7) et de Gestion des risques financiers (s\xE9ances 1 \xE0 4). \xC9cole Marocaine des Sciences de l'Ing\xE9nieur."]},hypotheses:[{id:"H01",txt:"PayMaroc compte environ 85 collaborateurs : Direction 4, Produit/Commerce 20, Tech/IT 32, Op\xE9rations 15, Support 12, Contr\xF4le interne 2."},{id:"H02",txt:"Ordre de grandeur d'activit\xE9 : environ 300 000 portefeuilles actifs et 80 000 op\xE9rations par jour."},{id:"H03",txt:"Le taux d'op\xE9rations annul\xE9es est pass\xE9 d'environ 1,2 % \xE0 2,8 % des op\xE9rations en 12 mois."},{id:"H04",txt:"Six interruptions ponctuelles de l'application sur les 6 derniers mois, d'une dur\xE9e de 20 \xE0 90 minutes."},{id:"H05",txt:"Un prestataire technologique unique (\xAB TechPay Cloud \xBB, nom fictif) fournit le moteur de traitement et l'h\xE9bergement ; le contrat ne comporte ni niveau de service chiffr\xE9 (SLA) ni plan de sortie."},{id:"H06",txt:"Environ deux mises en production par semaine, sans revue formelle du risque ni de la conformit\xE9 avant d\xE9ploiement."},{id:"H07",txt:"Les incidents sont consign\xE9s sur trois supports (e-mails, tickets du support, messagerie interne), sans grille de criticit\xE9 ni registre commun."},{id:"H08",txt:"Les fonds des clients sont cantonn\xE9s aupr\xE8s d'un partenaire bancaire principal unique."},{id:"H09",txt:"Le rapprochement et la tr\xE9sorerie op\xE9rationnelle sont rattach\xE9s aux Op\xE9rations (pas de fonction Finance distincte dans le p\xE9rim\xE8tre \xE9tudi\xE9)."},{id:"H10",txt:"L'autorit\xE9 de supervision des paiements existe mais ses exigences pr\xE9cises ne sont pas d\xE9taill\xE9es ici : aucune obligation r\xE9glementaire n'est invent\xE9e ni chiffr\xE9e."},{id:"H11",txt:"Les d\xE9lais cibles de la grille de criticit\xE9 (15 min, 1 h, 4 h, 24 h) et les cibles d'indicateurs sont des propositions du groupe."},{id:"H12",txt:"Les cotations cibles (apr\xE8s actions) et les niveaux de maturit\xE9 COSO sont des appr\xE9ciations qualitatives du groupe."},{id:"H13",txt:"Les incidents du tableau de suivi sont des exemples fictifs de d\xE9monstration."}],indices:[{id:1,txt:"Hausse des op\xE9rations annul\xE9es et interruptions ponctuelles de l'application"},{id:2,txt:"D\xE9pendance critique \xE0 un prestataire technologique externe"},{id:3,txt:"Incidents technologiques document\xE9s de mani\xE8re h\xE9t\xE9rog\xE8ne"},{id:4,txt:"Incidents transmis au support sans classification de criticit\xE9"},{id:5,txt:"R\xF4les mal d\xE9limit\xE9s entre op\xE9rations, technologie et contr\xF4le interne"},{id:6,txt:"Priorit\xE9 commerciale donn\xE9e au d\xE9ploiement rapide de nouvelles fonctionnalit\xE9s"}],cats:{O:"Op\xE9rationnel",F:"Financier",C:"Conformit\xE9"},cosoKeys:{env:"Environnement de contr\xF4le",risk:"\xC9valuation des risques",act:"Activit\xE9s de contr\xF4le",info:"Information et communication",mon:"Pilotage et surveillance"},actors:[{id:"DIR",nom:"Direction",type:"int",role:"Fixe la strat\xE9gie de croissance, arbitre, porte la responsabilit\xE9 finale.",objectif:"Croissance et rentabilit\xE9 ; r\xE9putation.",pouvoir:"\xC9lev\xE9",interet:"\xC9lev\xE9"},{id:"PRO",nom:"Produit / Commerce",type:"int",role:"Con\xE7oit et lance les nouvelles fonctionnalit\xE9s, porte les objectifs commerciaux.",objectif:"D\xE9lai de mise sur le march\xE9, nombre de fonctionnalit\xE9s, acquisition.",pouvoir:"\xC9lev\xE9",interet:"\xC9lev\xE9"},{id:"TEC",nom:"Tech / IT",type:"int",role:"D\xE9veloppe, d\xE9ploie, exploite l'application ; interface avec le prestataire.",objectif:"Livrer vite, stabilit\xE9 de la plateforme.",pouvoir:"\xC9lev\xE9",interet:"\xC9lev\xE9"},{id:"OPS",nom:"Op\xE9rations",type:"int",role:"Traite les op\xE9rations, g\xE8re les annulations, le rapprochement et la tr\xE9sorerie op\xE9rationnelle (H09).",objectif:"Flux r\xE9gl\xE9s sans erreur, fonds rapproch\xE9s.",pouvoir:"Moyen",interet:"\xC9lev\xE9"},{id:"SUP",nom:"Support",type:"int",role:"Re\xE7oit les r\xE9clamations et les signalements d'incidents, sans mandat de classification.",objectif:"R\xE9duire les d\xE9lais de r\xE9ponse aux clients.",pouvoir:"Faible",interet:"\xC9lev\xE9"},{id:"CIN",nom:"Contr\xF4le interne",type:"int",role:"\xC9value le dispositif, suit les d\xE9ficiences ; mandat et effectif limit\xE9s (H01).",objectif:"Dispositif fiable, anomalies suivies et corrig\xE9es.",pouvoir:"Faible",interet:"\xC9lev\xE9"},{id:"PRE",nom:"Prestataire technologique",type:"ext",role:"Fournit le moteur de traitement et l'h\xE9bergement (H05).",objectif:"Maximiser son revenu contractuel, limiter ses p\xE9nalit\xE9s.",pouvoir:"\xC9lev\xE9",interet:"Moyen"},{id:"CLI",nom:"Clients (utilisateurs)",type:"ext",role:"Utilisent le portefeuille pour payer et recevoir.",objectif:"Service disponible, op\xE9rations fiables, fonds en s\xE9curit\xE9.",pouvoir:"Moyen",interet:"\xC9lev\xE9"},{id:"BAN",nom:"Partenaires bancaires",type:"ext",role:"Cantonnent les fonds clients et assurent le r\xE8glement (H08).",objectif:"Flux r\xE9guliers et conformes, absence d'\xE9carts.",pouvoir:"\xC9lev\xE9",interet:"Moyen"},{id:"REG",nom:"R\xE9gulateur",type:"ext",role:"Supervise l'activit\xE9 de paiement (exigences non d\xE9taill\xE9es, H10).",objectif:"Stabilit\xE9 du service, protection des clients, transparence.",pouvoir:"\xC9lev\xE9",interet:"Moyen"}],risks:[{id:"R01",cat:"O",titre:"D\xE9faillance du prestataire technologique unique",cause:"Moteur de traitement et h\xE9bergement confi\xE9s \xE0 un seul prestataire ; contrat sans SLA ni plan de sortie (H05) ; aucune revue de performance du prestataire.",evenement:"Panne ou d\xE9gradation prolong\xE9e chez le prestataire, sans solution de repli.",cons:{fin:"Remboursements et gestes commerciaux, manque \xE0 gagner sur les commissions.",op:"Arr\xEAt des paiements, \xE9quipes mobilis\xE9es sans levier contractuel.",rep:"Perte de confiance des clients et des partenaires."},p:4,g:5,justP:"D\xE9pendance unique constat\xE9e et interruptions d\xE9j\xE0 observ\xE9es (indices 1 et 2).",justG:"Un arr\xEAt du prestataire stoppe l'ensemble du service de paiement.",indices:[2,1],basis:"Fait du cas",coso:"risk",lacune:"La d\xE9pendance au prestataire n'a pas \xE9t\xE9 \xE9valu\xE9e comme un risque : pas de SLA, pas de plan de continuit\xE9, pas de revue r\xE9guli\xE8re.",controle:"Revue contractuelle (SLA, plan de sortie), tableau de bord du prestataire, plan de repli test\xE9.",owner:"DIR",sources:["PRE","TEC"],impacted:["CLI","OPS","SUP","BAN"],target:{p:3,g:5}},{id:"R02",cat:"O",titre:"Mise en production d\xE9fectueuse provoquant une interruption",cause:"Priorit\xE9 commerciale au d\xE9ploiement rapide (indice 6) ; deux mises en production par semaine sans revue du risque (H06) ; validation avant d\xE9ploiement non formalis\xE9e.",evenement:"Une nouvelle version d\xE9ploy\xE9e d\xE9grade ou interrompt l'application.",cons:{fin:"Manque \xE0 gagner pendant l'indisponibilit\xE9, co\xFBt de correction en urgence.",op:"Retour arri\xE8re, mobilisation Tech/Ops/Support, risque d'annulations.",rep:"Avis n\xE9gatifs, perte de confiance dans la stabilit\xE9 du portefeuille."},p:4,g:4,justP:"Interruptions ponctuelles d\xE9j\xE0 observ\xE9es (H04) et rythme de d\xE9ploiement \xE9lev\xE9 sans filtre.",justG:"Indisponibilit\xE9 du service de paiement pour tous les clients, mais g\xE9n\xE9ralement de courte dur\xE9e (20\u201390 min, H04).",indices:[1,6],basis:"Fait du cas",coso:"act",lacune:"Absence de validation \xAB go/no-go \xBB avant mise en production et de contrepoids au rythme commercial.",controle:"Gate de mise en production : checklist, avis risque/conformit\xE9, voie rapide pour les changements mineurs.",owner:"TEC",sources:["PRO","DIR","TEC"],impacted:["CLI","OPS","SUP"],target:{p:2,g:4}},{id:"R03",cat:"F",titre:"Pertes et \xE9carts sur les op\xE9rations annul\xE9es",cause:"Instabilit\xE9 technique et interruptions (indice 1) ; absence de rapprochement syst\xE9matique des op\xE9rations annul\xE9es ou \xE9chou\xE9es (aucun contr\xF4le mentionn\xE9 dans le cas).",evenement:"Op\xE9rations annul\xE9es ou \xE9chou\xE9es o\xF9 le client est d\xE9bit\xE9 sans que le b\xE9n\xE9ficiaire soit cr\xE9dit\xE9 (ou l'inverse), non d\xE9tect\xE9es \xE0 temps.",cons:{fin:"Remboursements manuels, \xE9carts non rapproch\xE9s, pertes directes.",op:"Surcharge du support et des op\xE9rations, retraitements manuels.",rep:"R\xE9clamations clients, sentiment d'ins\xE9curit\xE9 sur les fonds."},p:4,g:4,justP:"Hausse des annulations d\xE9j\xE0 constat\xE9e (indice 1, H03).",justG:"Impact financier direct sur les clients et sur PayMaroc, avec effet de confiance.",indices:[1,2],basis:"Fait du cas",coso:"act",lacune:"Pas de contr\xF4le de rapprochement formalis\xE9 ni de seuil d'alerte sur les annulations.",controle:"Rapprochement quotidien des op\xE9rations annul\xE9es, seuil d'alerte, suivi des \xE9carts \xE0 J+1.",owner:"OPS",sources:["TEC","PRE"],impacted:["CLI","SUP","BAN"],target:{p:3,g:3}},{id:"R04",cat:"O",titre:"Incident critique trait\xE9 comme un incident ordinaire",cause:"Incidents transmis au support sans classification de criticit\xE9 (indice 4) ; pas de proc\xE9dure de d\xE9claration ni d'escalade ; r\xF4les flous (indice 5).",evenement:"Un incident grave n'est pas identifi\xE9 comme tel et reste dans la file du support.",cons:{fin:"Dur\xE9e d'indisponibilit\xE9 allong\xE9e, remboursements et gestes commerciaux accrus.",op:"Escalade tardive vers Tech et Direction, traitement dans le d\xE9sordre.",rep:"Clients sans information, image de service peu fiable."},p:5,g:4,justP:"Aucun incident n'est class\xE9 : la situation se reproduit \xE0 chaque incident (indice 4).",justG:"Un retard d'escalade amplifie chaque autre risque, sans \xEAtre un arr\xEAt total en soi.",indices:[4,3],basis:"Fait du cas",coso:"info",lacune:"Aucune grille de criticit\xE9 ni circuit d'escalade : l'information n'atteint pas la bonne personne au bon moment.",controle:"Grille de criticit\xE9 C1\u2013C4, d\xE9lais de prise en charge, escalade automatique des C1/C2.",owner:"OPS",sources:["SUP","DIR"],impacted:["CLI","TEC","DIR"],target:{p:2,g:4}},{id:"R05",cat:"O",titre:"Perte de tra\xE7abilit\xE9 et d'analyse des incidents",cause:"Incidents consign\xE9s sur trois supports diff\xE9rents (indice 3, H07) ; pas de registre commun ni de champs obligatoires.",evenement:"Incidents r\xE9currents non d\xE9tect\xE9s et causes racines non trait\xE9es ; reporting \xE0 la direction incomplet.",cons:{fin:"Co\xFBts r\xE9currents des m\xEAmes pannes, d\xE9cisions prises sur des chiffres incomplets.",op:"M\xEAmes incidents r\xE9p\xE9t\xE9s, temps perdu \xE0 reconstituer l'historique.",rep:"Information incompl\xE8te \xE0 donner aux partenaires ou au r\xE9gulateur."},p:4,g:3,justP:"H\xE9t\xE9rog\xE9n\xE9it\xE9 constat\xE9e de fa\xE7on syst\xE9matique (indice 3).",justG:"Impact indirect : il aggrave les autres risques sans provoquer de perte imm\xE9diate.",indices:[3],basis:"Fait du cas",coso:"mon",lacune:"Pas de registre unique ni de revue p\xE9riodique : les anomalies ne donnent pas lieu \xE0 un suivi ni \xE0 une am\xE9lioration.",controle:"Registre unique d'incidents, champs obligatoires, revue mensuelle des r\xE9currences.",owner:"CIN",sources:["SUP","TEC","OPS"],impacted:["DIR","CIN"],target:{p:2,g:3}},{id:"R06",cat:"O",titre:"D\xE9cisions et validations sans responsable clairement d\xE9sign\xE9",cause:"R\xF4les mal d\xE9limit\xE9s entre op\xE9rations, technologie et contr\xF4le interne (indice 5) ; Contr\xF4le interne r\xE9duit \xE0 2 personnes sans mandat explicite (H01).",evenement:"Une d\xE9cision (correction en production, arr\xEAt d'une fonctionnalit\xE9, communication) n'est prise par personne, ou par un acteur non habilit\xE9.",cons:{fin:"Erreurs co\xFBteuses, corrections doublonn\xE9es.",op:"D\xE9lais de d\xE9cision, conflits entre Tech et Op\xE9rations.",rep:"Communication incoh\xE9rente vers les clients."},p:4,g:3,justP:"Ambigu\xEFt\xE9 de r\xF4les constat\xE9e dans le cas (indice 5).",justG:"Impact surtout organisationnel, mais il s'amplifie en situation de crise.",indices:[5],basis:"Fait du cas",coso:"env",lacune:"Responsabilit\xE9s non formalis\xE9es et absence de d\xE9signation d'un arbitre pour le compromis vitesse / risque.",controle:"Matrice RACI sign\xE9e par la Direction, r\xE8gles d'arbitrage, revue annuelle.",owner:"DIR",sources:["DIR","TEC","OPS","CIN"],impacted:["OPS","TEC","SUP","CIN"],target:{p:2,g:3}},{id:"R07",cat:"O",titre:"Fraude ou acc\xE8s non autoris\xE9 sur les portefeuilles",cause:"S\xE9paration des t\xE2ches non d\xE9finie (indice 5) ; pression sur la vitesse de livraison (indice 6) ; droits d'acc\xE8s techniques non revus (Hypoth\xE8se de cadrage).",evenement:"Op\xE9rations frauduleuses ou manipulation de donn\xE9es non d\xE9tect\xE9es \xE0 temps.",cons:{fin:"Pertes, remboursements aux clients.",op:"Gel de comptes, enqu\xEAtes internes.",rep:"Atteinte grave \xE0 la confiance dans la s\xE9curit\xE9 des fonds."},p:2,g:5,justP:"Aucun incident de fraude dans le cas : risque d\xE9duit des lacunes de s\xE9paration des t\xE2ches (inf\xE9rence).",justG:"Une fraude touche directement les fonds des clients.",indices:[5,6],basis:"Inf\xE9rence",coso:"risk",lacune:"Le risque de fraude n'est pas identifi\xE9 ; droits d'acc\xE8s et s\xE9paration des t\xE2ches non formalis\xE9s.",controle:"Revue trimestrielle des droits d'acc\xE8s, s\xE9paration d\xE9veloppeur / valideur / d\xE9ployeur.",owner:"TEC",sources:["TEC","PRO"],impacted:["CLI","BAN"],target:{p:1,g:5}},{id:"R08",cat:"F",titre:"Insuffisance temporaire de liquidit\xE9 pour r\xE9gler les clients",cause:"Annulations et interruptions qui perturbent le rapprochement avec le partenaire bancaire (indices 1 et 2) ; d\xE9pendance au prestataire pour obtenir les \xE9tats de flux.",evenement:"\xC9cart non rapproch\xE9 entre fonds cantonn\xE9s et soldes des portefeuilles, ou fonds disponibles insuffisants pour un pic de retraits.",cons:{fin:"Retards de r\xE8glement, co\xFBt de financement d'urgence.",op:"Blocage ou limitation temporaire de retraits.",rep:"Panique des clients, perte de confiance."},p:2,g:5,justP:"Aucun indice direct de tension de liquidit\xE9 dans le cas (inf\xE9rence \xE0 partir des annulations).",justG:"Un d\xE9faut de r\xE8glement touche tous les clients concern\xE9s et la relation bancaire.",indices:[1,2],basis:"Inf\xE9rence",coso:"act",lacune:"Pas de contr\xF4le formalis\xE9 de concordance entre fonds cantonn\xE9s et soldes clients, ni de seuil d'alerte.",controle:"Rapprochement quotidien fonds cantonn\xE9s / soldes portefeuilles, seuil d'alerte, information de la Direction.",owner:"OPS",sources:["PRE","TEC"],impacted:["CLI","BAN"],target:{p:2,g:4}},{id:"R09",cat:"C",titre:"Nouvelle fonctionnalit\xE9 lanc\xE9e sans revue de conformit\xE9",cause:"Priorit\xE9 au d\xE9ploiement rapide (indice 6) ; Contr\xF4le interne absent du circuit de validation (indice 5) ; pas de revue de conformit\xE9 avant lancement (H06).",evenement:"Une fonctionnalit\xE9 est mise en ligne sans que les exigences de conformit\xE9 applicables (identification des clients, plafonds, lutte contre le blanchiment) aient \xE9t\xE9 v\xE9rifi\xE9es.",cons:{fin:"Sanctions potentielles, co\xFBt de mise en conformit\xE9 a posteriori.",op:"Retrait ou modification d'urgence de la fonctionnalit\xE9.",rep:"Atteinte \xE0 la cr\xE9dibilit\xE9 aupr\xE8s du r\xE9gulateur et des partenaires bancaires."},p:3,g:4,justP:"Aucun manquement constat\xE9 dans le cas ; le risque d\xE9coule de l'absence de revue (inf\xE9rence).",justG:"Atteinte potentielle \xE0 la capacit\xE9 d'exercer et \xE0 la relation bancaire.",indices:[6,5],basis:"Inf\xE9rence",coso:"act",lacune:"Pas de contr\xF4le de conformit\xE9 pr\xE9alable au lancement ; le Contr\xF4le interne n'est pas associ\xE9 \xE0 la validation.",controle:"Avis risque/conformit\xE9 obligatoire dans la gate de mise en production.",owner:"PRO",sources:["PRO","DIR"],impacted:["REG","CLI","BAN"],target:{p:1,g:4}},{id:"R10",cat:"C",titre:"Incident grave non remont\xE9 dans les d\xE9lais aux parties concern\xE9es",cause:"Aucune classification de criticit\xE9 (indice 4) ; pas d'escalade vers la Direction ni vers la conformit\xE9 ; r\xF4les flous (indice 5).",evenement:"Un incident grave (indisponibilit\xE9 longue, atteinte aux donn\xE9es) n'est pas communiqu\xE9 \xE0 temps aux partenaires bancaires ou au r\xE9gulateur.",cons:{fin:"Sanctions et p\xE9nalit\xE9s potentielles ; d\xE9lais de notification applicables \xE0 confirmer (H10).",op:"Gestion de crise improvis\xE9e.",rep:"Perte de cr\xE9dibilit\xE9 aupr\xE8s des autorit\xE9s et des partenaires."},p:2,g:4,justP:"Aucun incident grave rapport\xE9 dans le cas, mais le circuit d'escalade est absent (inf\xE9rence).",justG:"Cons\xE9quence potentielle sur la relation avec le r\xE9gulateur et les banques.",indices:[3,4,5],basis:"Inf\xE9rence",coso:"info",lacune:"Aucun circuit d'information externe : qui d\xE9cide de notifier, \xE0 qui, dans quel d\xE9lai ?",controle:"R\xE8gle de notification externe pour les incidents C1, d\xE9cision trac\xE9e dans le registre.",owner:"DIR",sources:["SUP","OPS"],impacted:["REG","BAN","CLI"],target:{p:1,g:4}},{id:"R11",cat:"F",titre:"D\xE9faillance ou blocage du partenaire bancaire unique",cause:"Fonds clients cantonn\xE9s aupr\xE8s d'un seul partenaire bancaire (H08) ; exposition externe non cartographi\xE9e.",evenement:"Retard, blocage ou rupture de la relation avec le partenaire bancaire.",cons:{fin:"Fonds temporairement indisponibles, retards de r\xE8glement.",op:"Interruption des retraits et virements.",rep:"Perte de confiance des clients."},p:1,g:5,justP:"Aucun indice dans le cas : \xE9v\xE9nement peu probable mais exposition de concentration (inf\xE9rence).",justG:"Impact potentiel sur l'ensemble des fonds clients.",indices:[2],basis:"Inf\xE9rence",coso:"risk",lacune:"Les expositions externes autres que le prestataire technologique ne sont pas cartographi\xE9es.",controle:"Revue annuelle de la d\xE9pendance bancaire, information de la Direction.",owner:"DIR",sources:["BAN"],impacted:["CLI","OPS"],target:{p:1,g:5}}],conflits:[{id:"K1",entre:["PRO","CIN"],txt:"Vitesse de mise sur le march\xE9 contre validation pr\xE9alable : le Contr\xF4le interne n'a ni mandat ni place dans le circuit de d\xE9cision de mise en production.",risques:["R02","R09"]},{id:"K2",entre:["PRO","TEC"],txt:"Plus de fonctionnalit\xE9s et plus vite contre qualit\xE9, tests et stabilit\xE9 de la plateforme.",risques:["R02","R03"]},{id:"K3",entre:["TEC","OPS"],txt:"Tech corrige et d\xE9ploie, Op\xE9rations subit les annulations et les \xE9carts : personne n'arbitre qui d\xE9cide d'un arr\xEAt ou d'un retour arri\xE8re.",risques:["R06","R03"]},{id:"K4",entre:["SUP","TEC"],txt:"Le Support re\xE7oit tous les signalements sans mandat de classification ; Tech re\xE7oit des demandes sans priorit\xE9.",risques:["R04","R05"]},{id:"K5",entre:["DIR","CIN"],txt:"La Direction arbitre entre croissance et contr\xF4le sans app\xE9tence au risque formalis\xE9e ; le Contr\xF4le interne alerte sans circuit d'escalade.",risques:["R06","R10"]},{id:"K6",entre:["PRE","DIR"],txt:"Le prestataire cherche \xE0 limiter ses engagements ; PayMaroc a besoin de disponibilit\xE9 garantie mais n'a ni SLA ni levier de sortie.",risques:["R01","R08"]}],raci:{cols:["DIR","PRO","TEC","OPS","SUP","CIN","PRE"],rows:[{act:"D\xE9clarer un incident (enregistrement dans le registre)",v:["","","R","A","R","I",""],constat:"Aucune r\xE8gle : chacun signale par son propre canal."},{act:"Classer la criticit\xE9 (C1 \xE0 C4)",v:["I","","C","A","R","I",""],constat:"Aucune classification ; le Support transmet sans crit\xE8re."},{act:"Escalader un incident critique (C1/C2)",v:["I","I","R","A/R","I","I","C"],constat:"Escalade au cas par cas, sans d\xE9lai."},{act:"Corriger / restaurer le service",v:["I","","A/R","C","I","","R"],constat:"Tech et prestataire agissent sans validation d'Op\xE9rations."},{act:"Informer les clients et partenaires",v:["C","C","C","A","R","I",""],constat:"Communication improvis\xE9e."},{act:"Valider une mise en production (go/no-go)",v:["A","R","R","C","I","C",""],constat:"D\xE9cision de fait par Produit/Tech, sans avis risque."},{act:"\xC9valuer le risque d'une nouvelle fonctionnalit\xE9",v:["I","A/R","C","C","","C",""],constat:"Aucune revue ; le Contr\xF4le interne n'est pas sollicit\xE9."},{act:"Piloter le prestataire (SLA, revue trimestrielle)",v:["A","","R","C","","I","C"],constat:"Pas de revue ni de SLA."},{act:"Tenir le registre et le tableau de suivi des incidents",v:["I","","C","C","R","A/R",""],constat:"Trois supports, aucun propri\xE9taire."},{act:"Rapprocher op\xE9rations annul\xE9es et fonds cantonn\xE9s",v:["I","","C","A/R","I","I",""],constat:"Contr\xF4le non formalis\xE9."},{act:"Revoir les droits d'acc\xE8s techniques",v:["I","","A/R","C","","C",""],constat:"Pas de revue p\xE9riodique."},{act:"Suivre les actions correctives (comit\xE9 mensuel)",v:["A","C","C","C","I","R",""],constat:"Pas de comit\xE9, pas de suivi."}]},coso:[{k:"env",q:"Les r\xF4les, l'\xE9thique et les responsabilit\xE9s sont-ils explicites ?",principes:"Principes 3 et 5 (structures, responsabilit\xE9s et obligation de rendre des comptes)",obs:["R\xF4les non d\xE9limit\xE9s entre Op\xE9rations, Technologie et Contr\xF4le interne (indice 5).","Priorit\xE9 donn\xE9e au d\xE9ploiement rapide sans contrepoids formalis\xE9 : le \xAB ton \xBB de la Direction favorise la vitesse (indice 6).","Contr\xF4le interne de 2 personnes (H01), sans mandat explicite dans le circuit de validation."],alerte:"Personne n'est d\xE9sign\xE9 pour recevoir une alerte et arbitrer.",info:"Les responsabilit\xE9s ne sont pas \xE9crites : l'information ne sait pas o\xF9 aller.",suivi:"Aucun acteur n'est tenu de rendre compte du suivi d'une anomalie.",lacune:"Pas de matrice de responsabilit\xE9s ni d'app\xE9tence au risque formalis\xE9e.",mat:2,cible:3},{k:"risk",q:"Les risques sont-ils identifi\xE9s et hi\xE9rarchis\xE9s ?",principes:"Principes 7, 8 et 9 (identification, fraude, changements significatifs)",obs:["Aucune cartographie des risques n'existait avant ce diagnostic (Hypoth\xE8se).","D\xE9pendance critique au prestataire non trait\xE9e comme un risque (indice 2).","Les nouvelles fonctionnalit\xE9s sont des changements significatifs lanc\xE9s sans analyse du risque (indice 6)."],alerte:"Sans risque identifi\xE9, il n'y a pas de seuil qui d\xE9clenche une alerte.",info:"Les risques de d\xE9pendance ne sont pas port\xE9s \xE0 la connaissance de la Direction.",suivi:"Pas de revue des risques dans le temps.",lacune:"Risques non identifi\xE9s ni hi\xE9rarchis\xE9s : d\xE9pendance externe, fraude, conformit\xE9 des lancements.",mat:2,cible:3},{k:"act",q:"Quelles validations, v\xE9rifications et s\xE9parations des t\xE2ches existent ?",principes:"Principes 10, 11 et 12 (activit\xE9s de contr\xF4le, contr\xF4les g\xE9n\xE9raux informatiques, politiques et proc\xE9dures)",obs:["Pas de validation go/no-go avant mise en production (indice 6, H06).","Qui d\xE9veloppe, qui d\xE9ploie et qui valide n'est pas s\xE9par\xE9 de fa\xE7on claire (indice 5).","Pas de rapprochement formalis\xE9 des op\xE9rations annul\xE9es (indice 1) ni de contr\xF4le sur le prestataire (indice 2)."],alerte:"Aucun contr\xF4le ne d\xE9clenche d'alerte avant la mise en production ou sur les annulations.",info:"Les contr\xF4les existants ne produisent pas de trace exploitable.",suivi:"Les \xE9carts ne sont pas suivis jusqu'\xE0 leur r\xE9solution.",lacune:"Contr\xF4les pr\xE9ventifs et de d\xE9tection absents sur les d\xE9ploiements, les annulations et le prestataire.",mat:2,cible:3},{k:"info",q:"L'information et les alertes circulent-elles efficacement ?",principes:"Principes 13, 14 et 15 (information de qualit\xE9, communication interne et externe)",obs:["Incidents document\xE9s diff\xE9remment selon les \xE9quipes (indice 3, H07).","Incidents transmis au support sans classification de criticit\xE9 (indice 4).","Aucun circuit d'escalade vers la Direction ni de communication externe structur\xE9e (clients, partenaires)."],alerte:"Une alerte critique ne se distingue pas d'une demande ordinaire.",info:"Trois supports, aucun format commun : l'information ne peut pas \xEAtre agr\xE9g\xE9e.",suivi:"Sans information comparable, aucun suivi n'est possible.",lacune:"Pas de grille de criticit\xE9, de circuit d'escalade ni de r\xE8gle de communication externe.",mat:1,cible:3},{k:"mon",q:"Les anomalies donnent-elles lieu \xE0 un suivi et \xE0 une am\xE9lioration ?",principes:"Principes 16 et 17 (\xE9valuations continues, communication des d\xE9ficiences)",obs:["Pas de registre commun : impossible de rep\xE9rer les incidents r\xE9currents (indice 3).","Hausse des op\xE9rations annul\xE9es constat\xE9e mais sans indicateur de suivi ni seuil (indice 1, H03).","Aucune revue p\xE9riodique des incidents ni remont\xE9e des d\xE9ficiences \xE0 la Direction."],alerte:"La d\xE9rive des annulations n'a d\xE9clench\xE9 aucune alerte formelle.",info:"Les d\xE9ficiences ne remontent pas \xE0 la Direction de fa\xE7on r\xE9guli\xE8re.",suivi:"Aucun tableau de suivi ; les actions correctives ne sont pas trac\xE9es.",lacune:"Pas de pilotage par indicateurs ni de comit\xE9 de revue.",mat:1,cible:3}],recos:[{id:"REC1",prio:1,vague:"Vague 1 (0\u201330 jours)",titre:"Grille de criticit\xE9 et circuit de d\xE9claration / escalade des incidents",risques:["R04","R10"],coso:"info",action:"Instaurer une grille C1\u2013C4, un formulaire unique de d\xE9claration, des d\xE9lais de prise en charge par niveau et une escalade automatique vers Direction et Contr\xF4le interne pour les C1/C2.",resp:"OPS",valide:"CIN",kpi:"Part des incidents class\xE9s dans les 30 minutes (cible 95 %) ; d\xE9lai moyen d'escalade des C1 (cible \u2264 15 min).",benefice:"Les incidents graves sont identifi\xE9s d\xE8s la r\xE9ception et atteignent le bon acteur ; r\xE9duction de la dur\xE9e d'exposition.",faisabilite:"\xC9lev\xE9e : proc\xE9dure et formulaire, sans investissement technique lourd.",limites:"D\xE9pend de la discipline du Support ; la grille devra \xEAtre ajust\xE9e apr\xE8s 3 mois d'usage."},{id:"REC2",prio:5,vague:"Vague 2 (30\u201390 jours)",titre:"Registre unique et tableau de suivi des incidents",risques:["R05","R04"],coso:"mon",action:"Remplacer les trois supports par un registre unique \xE0 champs obligatoires (criticit\xE9, cause, responsable, statut, \xE9ch\xE9ance) et revue mensuelle des r\xE9currences.",resp:"CIN",valide:"DIR",kpi:"Part des incidents consign\xE9s dans le registre (cible 100 %) ; part des incidents clos avec cause racine renseign\xE9e (cible 90 %).",benefice:"Tra\xE7abilit\xE9, d\xE9tection des r\xE9currences, base chiffr\xE9e pour la Direction.",faisabilite:"\xC9lev\xE9e : un tableur partag\xE9 suffit au d\xE9part.",limites:"Le Contr\xF4le interne (2 personnes) devra s'appuyer sur la saisie du Support et des Op\xE9rations."},{id:"REC3",prio:2,vague:"Vague 1 (0\u201330 jours)",titre:"Gate de mise en production avec voie rapide",risques:["R02","R09"],coso:"act",action:"Cr\xE9er une validation go/no-go \xE0 deux voies : voie rapide pour les changements mineurs, voie standard (avis risque/conformit\xE9) pour tout changement touchant les flux de paiement.",resp:"TEC",valide:"DIR",kpi:"Part des mises en production pass\xE9es par la gate (cible 100 %) ; nombre d'incidents post-d\xE9ploiement par mois.",benefice:"R\xE9duit les interruptions sans stopper le rythme commercial ; concilie vitesse et contr\xF4le.",faisabilite:"Moyenne : demande un arbitrage de la Direction sur le rythme.",limites:"Peut allonger certains d\xE9lais ; la voie rapide doit \xEAtre strictement d\xE9finie."},{id:"REC4",prio:3,vague:"Vague 1 (0\u201330 jours)",titre:"Gouvernance du prestataire technologique et des d\xE9pendances cl\xE9s",risques:["R01","R08","R11"],coso:"risk",action:"N\xE9gocier un SLA chiffr\xE9 et un plan de sortie, instaurer une revue trimestrielle du prestataire, tester un plan de repli, et revoir chaque ann\xE9e la d\xE9pendance bancaire.",resp:"DIR",valide:"CIN",kpi:"SLA sign\xE9 (oui/non) ; revues r\xE9alis\xE9es / revues pr\xE9vues (cible 4/4 par an) ; test du plan de repli (1 par an).",benefice:"Levier contractuel et visibilit\xE9 sur la performance du prestataire ; continuit\xE9 du service.",faisabilite:"Moyenne : d\xE9pend de la n\xE9gociation avec le prestataire.",limites:"Le risque r\xE9siduel reste \xE9lev\xE9 tant qu'une solution de secours compl\xE8te n'existe pas ; la n\xE9gociation est lanc\xE9e en vague 1 mais peut durer plus de 30 jours."},{id:"REC5",prio:6,vague:"Vague 2 (30\u201390 jours)",titre:"Matrice de responsabilit\xE9s (RACI) et s\xE9paration des t\xE2ches",risques:["R06","R07"],coso:"env",action:"Faire valider par la Direction la matrice RACI, s\xE9parer d\xE9veloppeur / valideur / d\xE9ployeur, et revoir les droits d'acc\xE8s chaque trimestre.",resp:"DIR",valide:"CIN",kpi:"Part des processus cl\xE9s couverts par un RACI sign\xE9 (cible 100 %) ; revues de droits r\xE9alis\xE9es (4 par an).",benefice:"Clarifie qui d\xE9cide ; r\xE9duit les d\xE9cisions orphelines et le risque de fraude interne.",faisabilite:"\xC9lev\xE9e : travail de formalisation.",limites:"Un RACI \xE9crit ne suffit pas sans appropriation par les \xE9quipes."},{id:"REC6",prio:4,vague:"Vague 1 (0\u201330 jours)",titre:"Rapprochement quotidien des annulations et des fonds cantonn\xE9s",risques:["R03","R08"],coso:"act",action:"Mettre en place un contr\xF4le quotidien de concordance (op\xE9rations annul\xE9es, fonds cantonn\xE9s / soldes clients) avec seuil d'alerte et suivi des \xE9carts \xE0 J+1.",resp:"OPS",valide:"CIN",kpi:"\xC9carts non rapproch\xE9s au-del\xE0 de 48 h (cible 0) ; op\xE9rations annul\xE9es trait\xE9es \xE0 J+1 (cible 98 %).",benefice:"D\xE9tection rapide des pertes et des \xE9carts ; protection des fonds clients.",faisabilite:"Moyenne : suppose l'acc\xE8s aux \xE9tats du prestataire.",limites:"D\xE9pend de la qualit\xE9 des donn\xE9es fournies par le prestataire."},{id:"REC7",prio:7,vague:"Vague 3 (90\u2013180 jours)",titre:"Comit\xE9 mensuel Risques & Incidents et app\xE9tence qualitative au risque",risques:["R02","R06"],coso:"mon",action:"R\xE9unir chaque mois Direction, Tech, Op\xE9rations, Produit et Contr\xF4le interne pour revoir le registre, les indicateurs et l'avancement des actions ; adopter une charte d'app\xE9tence qualitative.",resp:"DIR",valide:"CIN",kpi:"Comit\xE9s tenus / pr\xE9vus (cible 12/12) ; actions closes dans les d\xE9lais (cible 80 %).",benefice:"Arbitrage explicite du compromis vitesse / risque ; pilotage continu.",faisabilite:"\xC9lev\xE9e, mais demande du temps de Direction.",limites:"Risque de comit\xE9 formel sans d\xE9cisions si l'app\xE9tence n'est pas assum\xE9e."}],grille:{dims:[{k:"dispo",nom:"Disponibilit\xE9 du service",niv:["Aucun impact","D\xE9gradation l\xE9g\xE8re","Interruption partielle ou lenteurs fortes","Arr\xEAt complet des paiements"]},{k:"fin",nom:"Impact financier sur les clients ou PayMaroc",niv:["Aucun","Quelques op\xE9rations","\xC9carts significatifs \xE0 rembourser","Fonds clients touch\xE9s ou \xE9cart non expliqu\xE9"]},{k:"conf",nom:"Conformit\xE9 et donn\xE9es",niv:["Aucune","Doute \xE0 v\xE9rifier","Exigence potentiellement non respect\xE9e","Atteinte av\xE9r\xE9e aux donn\xE9es ou \xE0 une exigence"]},{k:"etendue",nom:"\xC9tendue (clients touch\xE9s)",niv:["Quelques-uns","Une partie limit\xE9e","Une part importante","Tous ou presque"]}],niveaux:[{c:"C1",nom:"Critique",delai:"Prise en charge \u2264 15 min",escalade:"Direction inform\xE9e \u2264 30 min ; cellule de crise ; d\xE9cision de notification externe trac\xE9e",qui:["DIR","OPS","TEC","CIN"]},{c:"C2",nom:"Majeur",delai:"Prise en charge \u2264 1 h",escalade:"Responsable Op\xE9rations et Tech ; Direction inform\xE9e en fin de journ\xE9e",qui:["OPS","TEC","CIN"]},{c:"C3",nom:"Mod\xE9r\xE9",delai:"Prise en charge \u2264 4 h",escalade:"Support de niveau 2 ; suivi dans le registre",qui:["SUP","OPS"]},{c:"C4",nom:"Mineur",delai:"Prise en charge \u2264 24 h",escalade:"Support de niveau 1 ; revue mensuelle",qui:["SUP"]}],etapes:[{n:1,t:"D\xE9tecter",d:"Client, supervision technique, \xE9quipe interne ou prestataire rep\xE8rent l'anomalie."},{n:2,t:"D\xE9clarer",d:"Formulaire unique, rempli en 5 minutes : qui, quoi, quand, service touch\xE9."},{n:3,t:"Classer",d:"Application de la grille : la criticit\xE9 retenue est le niveau le plus \xE9lev\xE9 parmi les quatre dimensions."},{n:4,t:"Router et escalader",d:"C1/C2 : escalade imm\xE9diate ; C3/C4 : traitement par le Support avec d\xE9lai cible."},{n:5,t:"Traiter",d:"Correction par Tech (et prestataire si besoin) ; information des clients par Support."},{n:6,t:"Cl\xF4turer",d:"Cause racine, action corrective, responsable et \xE9ch\xE9ance saisis dans le registre."},{n:7,t:"R\xE9viser",d:"Revue mensuelle des r\xE9currences au comit\xE9 Risques & Incidents."}]},incidents:[{id:"INC-001",date:"2026-10-06 09:12",source:"Client",desc:"Paiements marchands refus\xE9s pendant 40 minutes.",service:"Paiement marchand",crit:"C1",risque:"R01",resp:"OPS",statut:"Cl\xF4tur\xE9",pec:10,cause:"D\xE9gradation chez le prestataire",action:"Demande de SLA et de rapport d'incident",ech:"2026-11-20"},{id:"INC-002",date:"2026-10-13 14:30",source:"Supervision",desc:"Hausse des \xE9checs de transfert entre portefeuilles.",service:"Transferts",crit:"C2",risque:"R03",resp:"OPS",statut:"En cours",pec:55,cause:"\xC0 analyser",action:"Rapprochement des op\xE9rations annul\xE9es",ech:"2026-11-27"},{id:"INC-003",date:"2026-10-21 18:05",source:"\xC9quipe Tech",desc:"Version d\xE9ploy\xE9e le soir : lenteurs de l'application.",service:"Application mobile",crit:"C2",risque:"R02",resp:"TEC",statut:"Cl\xF4tur\xE9",pec:35,cause:"Mise en production sans test de charge",action:"Gate go/no-go",ech:"2026-12-04"},{id:"INC-004",date:"2026-10-28 10:40",source:"Support",desc:"D\xE9bit sans cr\xE9dit signal\xE9 par 12 clients.",service:"Portefeuille",crit:"C2",risque:"R03",resp:"OPS",statut:"Escalad\xE9",pec:120,cause:"Signalement non class\xE9, escalad\xE9 tardivement",action:"Grille de criticit\xE9",ech:"2026-11-30"},{id:"INC-005",date:"2026-11-03 08:20",source:"Client",desc:"Notification de paiement en double.",service:"Notifications",crit:"C4",risque:"R05",resp:"SUP",statut:"Cl\xF4tur\xE9",pec:300,cause:"Doublon de ticket",action:"Registre unique",ech:"2026-12-10"},{id:"INC-006",date:"2026-11-10 11:15",source:"Prestataire",desc:"Maintenance non annonc\xE9e du moteur de traitement.",service:"Moteur de traitement",crit:"C3",risque:"R01",resp:"TEC",statut:"En cours",pec:180,cause:"Absence de pr\xE9avis contractuel",action:"Revue trimestrielle du prestataire",ech:"2026-12-15"},{id:"INC-007",date:"2026-11-14 16:50",source:"Contr\xF4le interne",desc:"Fonctionnalit\xE9 de plafond modifi\xE9e sans avis de conformit\xE9.",service:"Plafonds",crit:"C3",risque:"R09",resp:"PRO",statut:"Ouvert",pec:0,cause:"Absence de revue de conformit\xE9",action:"Gate go/no-go",ech:"2026-12-04"},{id:"INC-008",date:"2026-11-17 07:45",source:"Supervision",desc:"\xC9cart non expliqu\xE9 entre soldes clients et fonds cantonn\xE9s.",service:"Rapprochement",crit:"C1",risque:"R08",resp:"OPS",statut:"Ouvert",pec:0,cause:"\xC0 analyser",action:"Rapprochement quotidien",ech:"2026-11-24"}],scenarios:[{id:"A",nom:"Vitesse d'abord (statu quo)",rap:5,risque:5,ctrl:1,txt:"D\xE9ploiement maximal sans filtre. Rapidit\xE9 \xE9lev\xE9e, mais risque r\xE9siduel et fragilit\xE9 des contr\xF4les au plus haut."},{id:"B",nom:"Prudence maximale (gel des lancements)",rap:1,risque:2,ctrl:5,txt:"Toute nouveaut\xE9 valid\xE9e en comit\xE9. Risque faible mais perte de comp\xE9titivit\xE9 : inadapt\xE9 \xE0 une fintech en croissance."},{id:"C",nom:"Croissance ma\xEEtris\xE9e (recommand\xE9)",rap:4,risque:3,ctrl:4,txt:"Voie rapide pour les changements mineurs, gate compl\xE8te pour les flux de paiement ; incidents class\xE9s et suivis."}],appetence:[{domaine:"Disponibilit\xE9 du paiement et fonds clients",niveau:"Tr\xE8s faible",regle:"Aucune mise en production touchant le paiement sans gate compl\xE8te ; incident C1 escalad\xE9 en 15 min."},{domaine:"Conformit\xE9 des nouvelles fonctionnalit\xE9s",niveau:"Tr\xE8s faible",regle:"Avis risque/conformit\xE9 obligatoire avant lancement."},{domaine:"Exp\xE9rience client hors paiement",niveau:"Mod\xE9r\xE9e",regle:"Voie rapide autoris\xE9e avec retour arri\xE8re pr\xE9vu."},{domaine:"D\xE9pendance au prestataire",niveau:"Faible, sous conditions",regle:"Accept\xE9e uniquement avec SLA, revue trimestrielle et plan de repli test\xE9."}],jury:[{q:"Pourquoi P \xD7 G et pas une mesure financi\xE8re du risque ?",r:"Le bar\xE8me du cours est qualitatif. P \xD7 G sert \xE0 classer, pas \xE0 mesurer : ce n'est ni une probabilit\xE9 statistique ni une perte attendue. Aucune m\xE9thode quantitative hors des s\xE9ances 1 \xE0 4 n'est utilis\xE9e."},{q:"Comment avez-vous justifi\xE9 des notes sans donn\xE9es ?",r:"Chaque note s'appuie sur un indice du cas. Quand aucun indice direct n'existe (R07, R08, R09, R10, R11), le risque est marqu\xE9 \xAB Inf\xE9rence \xBB avec une probabilit\xE9 basse, et les chiffres compl\xE9mentaires sont signal\xE9s \xAB Hypoth\xE8se \xBB."},{q:"Pourquoi R04 (incidents non class\xE9s) est-il \xE0 \xE9galit\xE9 avec la d\xE9faillance du prestataire ?",r:"Parce qu'il est quasi certain (P = 5, le d\xE9faut touche chaque incident) et qu'il amplifie tous les autres risques. R01 passe en premier \xE0 \xE9galit\xE9 de score gr\xE2ce \xE0 sa gravit\xE9 de 5."},{q:"Quel est le compromis entre vitesse commerciale et contr\xF4le ?",r:"Nous ne proposons pas de freiner la croissance : nous recommandons une gate \xE0 deux voies (rapide pour les changements mineurs, compl\xE8te pour le paiement). Le sc\xE9nario C r\xE9duit le risque en gardant la rapidit\xE9 \xE0 4 sur 5."},{q:"Qui est responsable de quoi ? Le Contr\xF4le interne valide-t-il les mises en production ?",r:"Non. Le propri\xE9taire du risque est l'op\xE9rationnel (Produit, Tech, Op\xE9rations) ; le Contr\xF4le interne donne un avis et suit les actions ; la Direction arbitre. C'est ce que montre le RACI cible."},{q:"Que montre le diagnostic COSO ?",r:"Les deux composantes les plus faibles sont Information et communication et Pilotage et surveillance (maturit\xE9 1 sur 4) : c'est l\xE0 que les alertes se perdent. Les trois autres sont \xE0 2 sur 4."},{q:"Quelles sont les limites de vos recommandations ?",r:"Le risque R01 reste \xE9lev\xE9 apr\xE8s actions (15) tant qu'aucune solution de repli compl\xE8te n'existe. Les cibles sont des hypoth\xE8ses. Un RACI \xE9crit ne suffit pas sans appropriation."},{q:"Pourquoi n'avez-vous pas utilis\xE9 de mod\xE8les quantitatifs ?",r:"Ils sont hors du p\xE9rim\xE8tre des s\xE9ances 1 \xE0 7 de contr\xF4le interne et 1 \xE0 4 de gestion des risques financiers (liste des techniques exclues au cadrage). Notre analyse reste qualitative."},{q:"Que faites-vous en premier, lundi matin ?",r:"REC1 : grille de criticit\xE9 et circuit d'escalade ; puis, dans les 30 premiers jours, REC3 (gate de mise en production), REC4 (lancement de la n\xE9gociation avec le prestataire) et REC6 (rapprochement quotidien)."},{q:"Comment mesurez-vous que \xE7a marche ?",r:"Par les indicateurs de chaque recommandation, par exemple : 95 % des incidents class\xE9s en 30 minutes, 100 % des mises en production pass\xE9es par la gate, 0 \xE9cart non rapproch\xE9 au-del\xE0 de 48 h."}]};const D=window.PM,$=(e,t=document)=>t.querySelector(e),$$=(e,t=document)=>[...t.querySelectorAll(e)],esc=e=>String(e??"").replace(/[&<>"]/g,t=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"})[t]),S={mode:"now",ov:{},tr:!1,plan:new Set,cat:""},A=e=>D.actors.find(t=>t.id===e),R=e=>D.risks.find(t=>t.id===e),ZL={hi:"\xC9lev\xE9",mid:"Mod\xE9r\xE9",lo:"Faible"},ZI={hi:"\u25B2",mid:"\u25C6",lo:"\u25CF"},CK=D.cosoKeys;function planPG(e){const t=S.ov[e.id]||{p:e.p,g:e.g},s=recosOf(e.id);if(!s.length)return t;const i=s.filter(a=>S.plan.has(a.id)).length/s.length;return{p:Math.round(t.p+(e.target.p-t.p)*i),g:Math.round(t.g+(e.target.g-t.g)*i)}}function sc(e){const t=S.mode==="target"?e.target:S.mode==="plan"?planPG(e):S.ov[e.id]||{p:e.p,g:e.g};return{p:t.p,g:t.g,s:t.p*t.g}}function base(e){return{p:e.p,g:e.g,s:e.p*e.g}}const zone=e=>e>=15?"hi":e>=6?"mid":"lo";function ranked(){return[...D.risks].sort((e,t)=>{const s=sc(e),i=sc(t);return i.s-s.s||i.g-s.g||i.p-s.p||e.id.localeCompare(t.id)})}const rankOf=e=>ranked().findIndex(t=>t.id===e)+1,recosOf=e=>D.recos